import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const container = new THREE.Group();
  const timelines = [];
  const disposables = [];

  const palette = {
    bg0: 0x14141a,
    bg1: 0x0b0b10,
    gridColor: 0xe8ecf2,
    borderColor: 0x26262f,
    accentLight: 0xff4450,
    accentDark: 0xc1121f,
    paper: 0xe8ecf2,
  };

  // Panel background: 3.2w x 2.2h
  const panelW = 3.2;
  const panelH = 2.2;
  const panelGeo = new THREE.PlaneGeometry(panelW, panelH);
  const panelMat = new THREE.MeshBasicMaterial({ color: palette.bg1 });
  const panelMesh = new THREE.Mesh(panelGeo, panelMat);
  container.add(panelMesh);
  disposables.push(panelGeo, panelMat);

  // Grid overlay
  addGridOverlay(panelMesh, panelW, panelH, palette, disposables);

  // Panel border
  addPanelBorder(panelMesh, panelW, panelH, palette, disposables);

  // Ghost preview group (left side)
  const ghostGroup = createGhostPreview(palette, disposables);
  ghostGroup.position.x = -0.7;
  ghostGroup.userData.opacity = 0.24;
  container.add(ghostGroup);

  // Text content (right side)
  const contentGroup = new THREE.Group();
  contentGroup.position.x = 0.5;

  // Headline text
  const textContent = config.textContent || [
    'Your ledger is empty.',
    'Commissioned pieces and saved references will appear here once you begin.',
    'BROWSE THE COLLECTION',
  ];

  if (ctx.fontAtlas && typeof ctx.fontAtlas.createText === 'function') {
    try {
      const headline = ctx.fontAtlas.createText(textContent[0], {
        size: 0.34,
        weight: 600,
        family: 'Lora',
        color: palette.paper,
      });
      if (headline) {
        headline.position.y = 0.4;
        headline.position.z = 0.01;
        contentGroup.add(headline);
      }
    } catch (e) {}

    try {
      const body = ctx.fontAtlas.createText(textContent[1], {
        size: 0.13,
        weight: 400,
        family: 'JetBrains Mono',
        color: palette.paper,
      });
      if (body) {
        body.position.y = 0;
        body.position.z = 0.01;
        contentGroup.add(body);
      }
    } catch (e) {}
  }

  container.add(contentGroup);

  // CTA button: 1.5w x 0.36h
  const ctaGeo = new THREE.PlaneGeometry(1.5, 0.36);
  const ctaMat = new THREE.MeshBasicMaterial({
    color: palette.accentLight,
  });
  const ctaButton = new THREE.Mesh(ctaGeo, ctaMat);
  ctaButton.position.y = -0.65;
  ctaButton.position.z = 0.005;
  container.add(ctaButton);
  disposables.push(ctaGeo, ctaMat);

  // CTA label
  if (ctx.fontAtlas && typeof ctx.fontAtlas.createText === 'function') {
    try {
      const ctaLabel = ctx.fontAtlas.createText(textContent[2], {
        size: 0.13,
        weight: 700,
        family: 'JetBrains Mono',
        color: 0x16161d,
      });
      if (ctaLabel) {
        ctaLabel.position.y = -0.65;
        ctaLabel.position.z = 0.01;
        container.add(ctaLabel);
      }
    } catch (e) {}
  }

  // Animations
  // Ghost breathing: 0.24 ↔ 0.34 over 2400ms
  const breatheTl = gsap.timeline({ repeat: -1, yoyo: true });
  breatheTl.to(
    ghostGroup.userData,
    {
      opacity: 0.34,
      duration: 2.4,
      ease: 'cubic-bezier(0.445, 0.05, 0.55, 0.95)',
      onUpdate() {
        ghostGroup.children.forEach((child) => {
          if (child.material) {
            child.material.opacity = ghostGroup.userData.opacity;
          }
        });
      },
    },
    0
  );
  timelines.push(breatheTl);

  // Mount animation: fade-up
  container.position.y = 0.2;
  container.userData.opacity = 0;
  gsap.to(container.position, {
    y: 0,
    duration: 0.5,
    ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
  });
  gsap.to(container.userData, {
    opacity: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
  });

  // CTA button press animation
  ctaButton.userData.handlers = {
    click: () => {
      gsap.to(ctaButton.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'cubic-bezier(0.175, 0.885, 0.32, 1.275)',
        yoyo: true,
        repeat: 1,
      });
    },
  };

  // Cleanup
  container.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    disposables.forEach((item) => {
      if (item && typeof item.dispose === 'function') {
        item.dispose();
      }
    });
  };

  return container;
}

function addGridOverlay(panelMesh, w, h, palette, disposables) {
  const gridPitch = 0.25;
  const halfW = w / 2;
  const halfH = h / 2;

  // Vertical lines
  for (let x = -halfW + gridPitch; x < halfW; x += gridPitch) {
    const geo = new THREE.BufferGeometry();
    geo.setAttribute(
      'position',
      new THREE.BufferAttribute(
        new Float32Array([x, -halfH, 0.001, x, halfH, 0.001]),
        3
      )
    );
    const mat = new THREE.LineBasicMaterial({
      color: palette.gridColor,
      transparent: true,
      opacity: 0.06,
      linewidth: 1,
    });
    const line = new THREE.Line(geo, mat);
    panelMesh.add(line);
    disposables.push(geo, mat);
  }

  // Horizontal lines
  for (let y = -halfH + gridPitch; y < halfH; y += gridPitch) {
    const geo = new THREE.BufferGeometry();
    geo.setAttribute(
      'position',
      new THREE.BufferAttribute(
        new Float32Array([-halfW, y, 0.001, halfW, y, 0.001]),
        3
      )
    );
    const mat = new THREE.LineBasicMaterial({
      color: palette.gridColor,
      transparent: true,
      opacity: 0.06,
      linewidth: 1,
    });
    const line = new THREE.Line(geo, mat);
    panelMesh.add(line);
    disposables.push(geo, mat);
  }
}

function addPanelBorder(panelMesh, w, h, palette, disposables) {
  const geo = new THREE.BufferGeometry();
  const halfW = w / 2 - 0.003;
  const halfH = h / 2 - 0.003;
  geo.setAttribute(
    'position',
    new THREE.BufferAttribute(
      new Float32Array([
        -halfW, -halfH, 0.001,
        halfW, -halfH, 0.001,
        halfW, halfH, 0.001,
        -halfW, halfH, 0.001,
        -halfW, -halfH, 0.001,
      ]),
      3
    )
  );
  const mat = new THREE.LineBasicMaterial({
    color: palette.borderColor,
    linewidth: 1,
  });
  const line = new THREE.Line(geo, mat);
  panelMesh.add(line);
  disposables.push(geo, mat);
}

function createGhostPreview(palette, disposables) {
  const group = new THREE.Group();

  // Watch-card wireframe: 1.1w x 1.4h
  const w = 0.55;
  const h = 0.7;

  const cardGeo = new THREE.BufferGeometry();
  cardGeo.setAttribute(
    'position',
    new THREE.BufferAttribute(
      new Float32Array([
        -w, -h, 0, w, -h, 0, w, -h, 0, w, h, 0, w, h, 0, -w, h, 0, -w, h, 0,
        -w, -h, 0,
      ]),
      3
    )
  );
  const cardMat = new THREE.LineBasicMaterial({
    color: palette.gridColor,
    transparent: true,
    opacity: 0.3,
    linewidth: 0.5,
  });
  const cardLine = new THREE.LineSegments(cardGeo, cardMat);
  group.add(cardLine);
  disposables.push(cardGeo, cardMat);

  // Dial circle: 0.55 diameter
  const dialGeo = new THREE.CircleGeometry(0.275, 64);
  const dialMat = new THREE.LineBasicMaterial({
    color: palette.gridColor,
    transparent: true,
    opacity: 0.22,
    linewidth: 0.5,
  });
  const dial = new THREE.LineSegments(dialGeo, dialMat);
  group.add(dial);
  disposables.push(dialGeo, dialMat);

  // Text bars: 0.7w x 0.06h
  for (let i = 0; i < 2; i++) {
    const barGeo = new THREE.PlaneGeometry(0.7, 0.06);
    const barMat = new THREE.MeshBasicMaterial({
      color: palette.gridColor,
      transparent: true,
      opacity: 0.22,
    });
    const bar = new THREE.Mesh(barGeo, barMat);
    bar.position.y = 0.25 - i * 0.1;
    bar.position.z = 0.001;
    group.add(bar);
    disposables.push(barGeo, barMat);
  }

  return group;
}
